import { Component, OnInit } from '@angular/core';
import { AttendanceService } from '../../../services';
import { AuthService } from '../../../services/auth/auth.service';
@Component({
  selector: 'app-attendance',
  templateUrl: './attendance.component.html',
  styleUrls: ['./attendance.component.css']
})
export class AttendanceComponent implements OnInit {

  attendanceRecords: any[] = [];
  groups: string[] = [];

  searchText: string = '';
  selectedStatus: string = 'All Status';
  selectedGroup: string = 'All Groups';
  selectedDate: string = '';

  isModalOpen: boolean = false;
  isDetailsModalOpen: boolean = false;
  selectedRecord: any = null;

  constructor(private attendanceService: AttendanceService, private authService: AuthService) { }

  ngOnInit(): void {
    const role = this.authService.getUserRole();


    if (role === 'student' || role === 'parent') {
      alert('Not Allowed');
      return;
    }
    this.fetchAttendanceData();
  }

  fetchAttendanceData(): void {
    this.attendanceService.getAllAttendance().subscribe({
      next: (res: any) => {
        if (res.success) {
          this.attendanceRecords = res.data.map((item: any) => ({
            _id: item._id,
            studentName: item.studentId?.userId?.name || 'Unknown',
            studentId: item.studentId?.studentCode || 'N/A',
            group: item.groupId?.groupName || 'General',
            date: item.date ? item.date.split('T')[0] : '',
            status: item.status,
            time: item.createdAt ? new Date(item.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '-'
          }));

          this.groups = Array.from(new Set(this.attendanceRecords.map(r => r.group)));
        }
      },
      error: (err: any) => {
        console.error('Error fetching attendance:', err);
      }
    });
  }

  get canEdit(): boolean {
    const role = this.authService.getUserRole();
    return role === 'secretary' || role === 'teacher' || role === 'admin';
  }
  saveAttendance(): void {
    if (!this.selectedRecord) return;

    this.attendanceService.updateAttendance(this.selectedRecord._id, {
      status: this.selectedRecord.status,
      date: this.selectedRecord.date
    }).subscribe({
      next: (res: any) => {
        if (res.success) {
          this.fetchAttendanceData();
          this.isModalOpen = false;
          this.selectedRecord = null;
        }
      },
      error: (err: any) => {
        console.error('Error updating attendance:', err);
      }
    });
  }

  get filteredRecords(): any[] {
    const search = this.searchText.toLowerCase().trim();
    return this.attendanceRecords.filter(record => {
      const matchesSearch = !search || record.studentName.toLowerCase().includes(search) || record.studentId.toLowerCase().includes(search);
      const matchesStatus = this.selectedStatus === 'All Status' || record.status === this.selectedStatus;
      const matchesGroup = this.selectedGroup === 'All Groups' || record.group === this.selectedGroup;
      const matchesDate = !this.selectedDate || record.date === this.selectedDate;
      return matchesSearch && matchesStatus && matchesGroup && matchesDate;
    });
  }

  get totalStudents(): number { return this.attendanceRecords.length; }
  get presentCount(): number { return this.attendanceRecords.filter(r => r.status === 'Present').length; }
  get absentCount(): number { return this.attendanceRecords.filter(r => r.status === 'Absent').length; }
  get lateCount(): number { return this.attendanceRecords.filter(r => r.status === 'Late').length; }
  get excusedCount(): number { return this.attendanceRecords.filter(r => r.status === 'Excused').length; }

  getInitials(name: string): string {
    return name ? name.split(' ').map((w: string) => w.charAt(0)).join('').substring(0, 2).toUpperCase() : 'ST';
  }

  viewAttendance(record: any): void {
    this.selectedRecord = record;
    this.isDetailsModalOpen = true;
  }

  closeDetailsModal(): void {
    this.isDetailsModalOpen = false;
    this.selectedRecord = null;
  }

  editAttendance(record: any): void {
    this.selectedRecord = { ...record };
    this.isModalOpen = true;
  }

  closeModal(): void {
    this.isModalOpen = false;
    this.selectedRecord = null;
  }
}
